<script setup lang="ts">
import { onMounted, reactive, ref } from 'vue'
import { ElMessage, ElMessageBox } from 'element-plus'
import { Search, Refresh, Delete, Lock, Unlock, Key } from '@element-plus/icons-vue'
import { changeAppUserStatus, deleteAppUser, getAppUserPage, resetAppUserPassword, type AppUserAdmin } from '@/api/user'
import type { PageResult } from '@/types/api'
const loading=ref(false);const rows=ref<AppUserAdmin[]>([]);const total=ref(0);const query=reactive({current:1,size:10,username:'',nickname:'',status:undefined as number|undefined})
const statusLabel=(s:number)=>s===1?'正常':'禁用';const statusType=(s:number)=>s===1?'success':'danger'
async function load(){loading.value=true;try{const r:PageResult<AppUserAdmin>=await getAppUserPage(query);rows.value=r.records||[];total.value=r.total||0}finally{loading.value=false}}
function search(){query.current=1;load()};function reset(){query.username='';query.nickname='';query.status=undefined;search()}
async function toggle(raw:unknown){const row=raw as AppUserAdmin;const next=row.status===1?0:1;await changeAppUserStatus(row.id,next);ElMessage.success(next===1?'已启用':'已禁用');load()}
async function resetPassword(raw:unknown){const row=raw as AppUserAdmin;const result=await ElMessageBox.prompt('请输入 6-32 位新密码','重置密码',{inputType:'password',inputValidator:v=>!!v&&v.length>=6&&v.length<=32||'密码长度须为 6-32 位'});await resetAppUserPassword(row.id,result.value);ElMessage.success('密码已重置')}
async function remove(raw:unknown){const row=raw as AppUserAdmin;await ElMessageBox.confirm('删除后用户及其登录权限将失效，确定继续吗？','删除用户',{type:'warning'});await deleteAppUser(row.id);ElMessage.success('删除成功');load()}
onMounted(load)
</script>
<template><div class="user-list"><el-card class="filter" shadow="never"><el-form :inline="true"><el-form-item label="用户名"><el-input v-model="query.username" clearable/></el-form-item><el-form-item label="昵称"><el-input v-model="query.nickname" clearable/></el-form-item><el-form-item label="状态"><el-select v-model="query.status" clearable><el-option label="正常" :value="1"/><el-option label="禁用" :value="0"/></el-select></el-form-item><el-form-item><el-button type="primary" :icon="Search" @click="search">查询</el-button><el-button :icon="Refresh" @click="reset">重置</el-button></el-form-item></el-form></el-card><el-card shadow="never"><el-table v-loading="loading" :data="rows" border stripe><el-table-column prop="id" label="ID" width="70"/><el-table-column prop="username" label="用户名" width="150"/><el-table-column prop="nickname" label="昵称" width="150"/><el-table-column prop="email" label="邮箱" min-width="180"/><el-table-column label="状态" width="90"><template #default="s"><el-tag :type="statusType(s.row.status)">{{statusLabel(s.row.status)}}</el-tag></template></el-table-column><el-table-column prop="lastLoginAt" label="最后登录" width="170"/><el-table-column prop="createTime" label="注册时间" width="170"/><el-table-column label="操作" width="260" fixed="right"><template #default="s"><el-button link :type="s.row.status===1?'warning':'success'" :icon="s.row.status===1?Lock:Unlock" @click="toggle(s.row)">{{s.row.status===1?'禁用':'启用'}}</el-button><el-button link type="primary" :icon="Key" @click="resetPassword(s.row)">重置密码</el-button><el-button link type="danger" :icon="Delete" @click="remove(s.row)">删除</el-button></template></el-table-column><template #empty><el-empty description="暂无用户"/></template></el-table><div class="pagination"><el-pagination v-model:current-page="query.current" v-model:page-size="query.size" :total="total" :page-sizes="[10,20,50]" layout="total,sizes,prev,pager,next" @size-change="search" @current-change="load"/></div></el-card></div></template>
<style scoped lang="scss">.user-list{padding:16px}.filter{margin-bottom:16px}.pagination{margin-top:16px;display:flex;justify-content:flex-end}</style>
